using System.Runtime.InteropServices;

namespace eQuantic.UI.Native.Shell.Windows;

/// <summary>
/// The slice of Win32 a Photon window stands on — user32, gdi32, kernel32, dwmapi and imm32 —
/// as typed <c>LibraryImport</c> externs over the C ABI, the same "slim owned bindings" the Apple
/// shells use for objc_msgSend and the Vulkan backend uses for the loader. Nothing here is
/// generated by a binding framework and nothing is third-party: every function is exported by a
/// DLL that ships with Windows, and every constant is spelled from the SDK headers beside the call
/// that uses it.
/// </summary>
internal static unsafe partial class Win32
{
    private const string User32 = "user32.dll";
    private const string Gdi32 = "gdi32.dll";
    private const string Kernel32 = "kernel32.dll";
    private const string Dwmapi = "dwmapi.dll";
    private const string Imm32 = "imm32.dll";
    private const string Shell32 = "shell32.dll";

