    // ---- Helpers ------------------------------------------------------------------------------

    public static int LoWord(nint value) => (short)(value & 0xFFFF);

    public static int HiWord(nint value) => (short)((value >> 16) & 0xFFFF);

    public static int LoWord(nuint value) => (ushort)(value & 0xFFFF);

    public static int HiWord(nuint value) => (short)((value >> 16) & 0xFFFF);

    /// <summary>A pointer message's client coordinates — SIGNED, because a captured drag reports
    /// positions left of and above the window as negatives, and a ushort read would put them at
    /// the far edge of a 65,535-pixel screen.</summary>
    public static (int X, int Y) PointOf(nint lParam) => (LoWord(lParam), HiWord(lParam));

    public static bool IsDown(int virtualKey) => (GetKeyState(virtualKey) & 0x8000) != 0;
